#!/usr/bin/env bash
#
# Run the clone integration harness end to end.
#
#   ./Run.sh              both legs (meadow-endpoints 4.x and 2.x sources)
#   ./Run.sh 4x           only the current-stack source
#   ./Run.sh 2x           only the legacy-stack source
#
# Set SOURCE_ENGINE=mssql to point the 4.x leg at SQL Server instead of
# PostgreSQL (also start it: docker compose --profile mssql up -d mssql).

set -euo pipefail

cd "$(dirname "$0")"

LEGS=${1:-both}
EXIT_CODE=0

echo "==> Starting databases"
docker compose up -d postgres mysql

echo "==> Building and starting source APIs"
docker compose up -d --build source-4x source-2x

echo "==> Building the clone runner (patched with the local working tree)"
docker compose build clone

run_leg()
{
	local tmpLeg=$1
	echo
	echo "==> Validating the ${tmpLeg} source leg"
	if ! docker compose run --rm clone node validate.js "${tmpLeg}"; then
		EXIT_CODE=1
	fi
}

if [ "${LEGS}" = "both" ] || [ "${LEGS}" = "4x" ]; then
	run_leg 4x
fi

if [ "${LEGS}" = "both" ] || [ "${LEGS}" = "2x" ]; then
	run_leg 2x
fi

echo
if [ "${EXIT_CODE}" -eq 0 ]; then
	echo "==> All legs passed."
else
	echo "==> FAILURES — see the [fail] lines above."
fi

exit "${EXIT_CODE}"
